        [HttpPost]
        [SessionExpireFilterAttribute]
        [ValidateInput(false)]
        [ValidateSessionFilterSpokLoginInternal]
        public ActionResult AddBulkImportsWipro(AddPQPersonalBulkImportViewModel model)
        {
            try
            {
                if (model.ClientRowID > 0)
                {
                    int fileNo = repoPQClientCandiBulkUpload.GetNoOfExcelFileByClientID(model.ClientRowID);
                    var ClientDetails = repoPQClient.GetPQClientForCadiCodeGenById(model.ClientRowID);
                    if (model.UploadDoc != null && model.UploadDoc.ContentLength > 0)/*&& model.UploadDoc1 != null && model.UploadDoc1.ContentLength > 0*/
                    {
                        fileNo++;
                        string Extension = Path.GetExtension(model.UploadDoc.FileName).ToLower();
                        //string ExtensionSOW = Path.GetExtension(model.UploadDoc1.FileName).ToLower();
                        string FileName = (ClientDetails.ClientName + "_" + fileNo.ToString()).Replace(" ", "_").Replace("-", "_").Replace("/", "_") + Extension;
                        string FolderPath = ConfigurationManager.AppSettings["clientCanidatetemplate"];
                        // HttpPostedFileBase
                        string FilePath = Server.MapPath(FolderPath + FileName);
                        model.UploadDoc.SaveAs(Server.MapPath(FolderPath + FileName));

                        // int res = SaveClientCandidateUploadFileWithChecks(model.ClientRowID, FileName, model.CandidateCheckOrPackage);
                        string TicketNo = model.ClientRowID + "-" + DateTime.Now.Date.ToString("dd-MM-yyyy") + "-" + fileNo;
                        //if (res > 0)
                        //{
                        if (Extension != ".xls" && Extension != ".xlsx")/*&& (ExtensionSOW != ".xls" || ExtensionSOW != ".xlsx")*/
                        {
                            ViewBag.ErrorMsg = "Invalid file type. Please upload an Excel file.";
                            return View();
                        }
                        if (model.ClientRowID == 317)
                        {


                            ImportExcelAndSaveCandidateByBulkUploadWT(FilePath, Extension, "Yes", model, TicketNo);
                        }
                        else if (model.ClientRowID == 327)
                        {
                            ImportExcelAndSaveCandidateByBulkUploadDOP(FilePath, Extension, "Yes", model, TicketNo);
                        }

                        ModelState.Clear();
                        return RedirectToAction("AddBulkImportsWipro", "ClientServicing", new { ticid = TicketNo, ClientRowID = model.ClientRowID });
                        //}
                    }
                    else
                    {
                        ViewBag.ErrorMsg = "Please Select Excel Document!";
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "Invalid ClientID!";
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);
        }

