        private void ImportExcelAndSaveCandidateByBulkUploadWT(string FilePath, string Extension, string isHDR, AddPQPersonalBulkImportViewModel model, string TicketNo) //isHDR - means Include header Yes or No
        {
            try
            {
                string Designation = Session["Designation"].ToString();
                ClientCustomize cc = new ClientCustomize();
                string conStr = "";
                switch (Extension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, FilePath, isHDR);
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();

                //Insert into database CandidatesBulkImport table
                if (dt.Rows.Count > 0)
                {
                    //string lblMsg = clsCommanMethod.MsgBox("Total Candidates : " + dt.Rows.Count.ToString());
                    int countSuccess = 0;
                    int countDuplicate = 0;
                    string Email = string.Empty;
                    string MobileNo = string.Empty;
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        Email = Convert.ToString(dt.Rows[i]["STR_CANDIDATE_EMAIL"]);

                        model.EmailID = Email;
                        MobileNo = Convert.ToString(dt.Rows[i]["Contact Number"]);
                        if (MobileNo.Length > 10)
                        {
                            if (MobileNo.Length == 12)
                            {
                                model.MobileNo = MobileNo.Remove(0, 2);
                            }
                            else if (MobileNo.Length == 11)
                            {
                                model.MobileNo = MobileNo.Remove(0, 1);
                            }
                            else if (MobileNo.Length == 13)
                            {
                                model.MobileNo = MobileNo.Remove(0, 3);
                            }
                        }
                        model.MobileNo = MobileNo;
                        model.Name = dt.Rows[i]["EMPLOYEE_NAME"].ToString();
                        model.VoterIDCardNo = null;
                        string packageName = dt.Rows[i]["ACCOUNT_NAME"].ToString();
                        string PatternName = dt.Rows[i]["BGV_PATTERN_NAME"].ToString();
                        string countryName = dt.Rows[i]["COUNTRY"].ToString();
                        model.DrivingLicenseNo = null;
                        model.AadhaarCardNo = null;
                        model.PassportNo = null;
                        model.PanCardNo = null;
                        model.FatherName = null;
                        model.MiddleName = null;
                        model.LastName = null;
                        //========================================================
                        model.Education = dt.Rows[i]["Education"].ToString();
                        model.Employment = dt.Rows[i]["Employment"].ToString();
                        model.Address = dt.Rows[i]["Address"].ToString();
                        model.Criminal = dt.Rows[i]["Criminal"].ToString();
                        model.Identity = dt.Rows[i]["Identity"].ToString();
                        model.Database = dt.Rows[i]["Database"].ToString();
                        model.Additional_Professional_Certifications = dt.Rows[i]["Additional Professional Certifications"].ToString();
                        model.Drug_Test_Verification = dt.Rows[i]["Drug Test Verification"].ToString();
                        model.Credit_History_Verification = dt.Rows[i]["Credit History Verification"].ToString();
                        model.Family_Relationship = dt.Rows[i]["Family Relationship"].ToString();
                        model.External_Directorship = dt.Rows[i]["External Directorship"].ToString();
                        model.Self_Employment_Directorship = dt.Rows[i]["Self Employment/Directorship"].ToString();
                        model.Facis_III = dt.Rows[i]["Facis III"].ToString();
                        model.Entitlement_to_Work = dt.Rows[i]["Entitlement to Work"].ToString();
                        model.Professional_Reference_Verification = dt.Rows[i]["Professional Reference Verification"].ToString();
                        model.Professional_License_Check = dt.Rows[i]["Professional License Check"].ToString();
                        //========================================================
                        model.ClientRefID = dt.Rows[i]["RESUME_NUMBER"].ToString();
                        if (dt.Rows[i]["Date of Birth"].ToString() != "")
                            model.DOB = Convert.ToDateTime(dt.Rows[i]["Date of Birth"].ToString());
                        else
                            model.DOB = null;

                        if (!string.IsNullOrEmpty(model.Name))
                        {
                            //if(1==1)
                            //{ 
                            model.CreatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                            if (!repoPQPersonal.IsCandidateExistWiproBulk(model.ClientRowID, model.VoterIDCardNo, model.DrivingLicenseNo, model.AadhaarCardNo, model.PassportNo, model.PanCardNo, model.ClientRefID))
                            {
                                model.MiddleName = null;
                                model.LastName = null;
                                model.Gender = dt.Rows[i]["Gender"].ToString(); ;
                                if (model.Gender.ToLower() == "male")
                                {
                                    model.Gender = "Male";
                                    model.CandTitle = "Mr.";
                                }
                                else if (model.Gender.ToLower() == "female")
                                {
                                    model.CandTitle = "Mrs.";
                                }
                                else
                                {
                                    model.CandTitle = null;
                                }
                                model.EmployeeID = dt.Rows[i]["RESUME_NUMBER"].ToString();

                                model.CandidateCode = GenrateCandidateCode(model.ClientRowID);
                                model.CompanyRefNo = GetCompanyRefNo(model.ClientRowID);
                                model.CreatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                                model.CreatedDate = DateTime.Now;
                                model.FromType = "Company Cases";
                                model.DetailsEnteredBy = "Company";
                                model.CaseStatus = "Allocated";
                                model.Status = 1;
                                model.ClientUserName = null;
                                //if (dt.Rows[i]["DateofJoining"].ToString().Length > 4)
                                //{
                                model.DateofJoining = null;
                                //Convert.ToDateTime(dt.Rows[i]["DateofJoining"].ToString());
                                // }
                                model.PlaceOfJoining = null;
                                //dt.Rows[i]["PlaceOfJoining"].ToString();
                                model.AlternateNo = null;
                                model.ProcessName = null;
                                model.ProjectId = null;
                                model.ProjectName = null;


                                model.Grade = "";

                                model.UAN = dt.Rows[i]["UAN"].ToString();



                                model.PID = "";
                                model.SDO_Code = "";
                                model.COE_Code = "";
                                model.UID = "";
                                model.OHR_Taleo_ID = "";
                                model.Band = "";
                                model.Designation_Genpact = "";

                                model.AlternateEmailID = null;
                                model.Entity = dt.Rows[i]["Entity"].ToString();
                                model.AccountName = dt.Rows[i]["ACCOUNT_NAME"].ToString();
                                model.PatternName = dt.Rows[i]["BGV_PATTERN_NAME"].ToString();
                                model.CandidateType = null;


                                model.Location = "";



                                //if (Designation == "Team Leader-CS")
                                //{
                                model.CreatedBySource = "InternalBulkWiproSpoc";
                                //}
                                PQClientCodeHolidaysViewModel client = repoPQClient.GetPQClientCodeHolidaysById(model.ClientRowID);
                                model.TAT = repoPQPersonal.GetClientTATByCandidateId(model.ClientRowID);
                                model.CaseType = "Normal";

                                // OrderDate And DeliveryDate
                                DateTime oDate = DateTime.Now;
                                model.OrderDate = oDate;
                                model.DeliveryDate = GetDeliveryDate(oDate, model.TAT, client);
                                DataTable dtuser = cc.getClientUserIdByName(model.ClientUserName, model.ClientRowID);
                                if (dtuser.Rows.Count > 0)
                                {
                                    model.ClientUserRowID = Convert.ToInt32(dtuser.Rows[0]["ClientUserRowID"]);
                                }
                                else
                                {
                                    model.ClientUserRowID = 0;
                                }
                                //// Check Duplicate Name
                                model.CandidateDuplicateList = repoPQPersonal.CheckCandidateduplicateNameFromDETL(model.ClientRowID, model.Name, model.MiddleName, model.LastName, "", model.MobileNo, model.EmployeeID);
                                if (model.CandidateDuplicateList.Count() > 0)
                                {
                                    cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, true, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);

                                }
                                else
                                {
                                    cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, false, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);
                                }
                                int Res = 0;

                                if (model.CandidateDuplicateList.Count() == 0)
                                {
                                    Res = repoPQPersonal.AddCandidateNew(model);
                                    model.PersonalRowID = Res;
                                }
                                else
                                {
                                    Res = -1;
                                }
                                if (Res == 0)
                                {
                                    ViewBag.ErrorMsg = ViewBag.ErrorMsg + " Mobile no and email id should not be duplicate";
                                }
                                else
                                {
                                    ViewBag.ErrorMsg = "Reference Generated Successfully";
                                }



                                if (Res > 0)
                                {
                                    //model.PersonalRowID = repoPQPersonal.GetPQPersonalByCandidateCode(model.CompanyRefNo).PersonalRowID;

                                    #region Save LogTransaction Details
                                    clsCommonMethods.AddPQLogTrasaction(model.PersonalRowID, "Add Candidate", "Candidate Reference Generated", "Input", "Insert");
                                    #endregion

                                    #region Case/Check Action History Save 
                                    clsCommonMethods.AddCaseActionHistory(model.PersonalRowID, "Allocated-TL", "Securitas Id Generated by Import: " + model.CompanyRefNo);
                                    #endregion

                                    SavePackageOrCheckWithCandidateAsBulkImportWT(model, packageName, countryName, PatternName);
                                    cc.UpdateCaseStatus(model.PersonalRowID, 6, 0);
                                    countSuccess++;

                                }
                            }
                            else
                            {
                                cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, true, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);
                                countDuplicate++;
                            }

                        }

                    }




                    TempData["SuccessMsg"] = countSuccess.ToString() + " Candidate(s) added successfully!";
                    if (countDuplicate > 0)
                    {
                        TempData["ErrorMsg"] = countDuplicate.ToString() + " Candidate(s) already exist!";
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "No candidate found!";
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }

        private void ImportExcelAndSaveCandidateByBulkUploadDOP(string FilePath, string Extension, string isHDR, AddPQPersonalBulkImportViewModel model, string TicketNo) //isHDR - means Include header Yes or No
        {
            try
            {
                string Designation = Session["Designation"].ToString();
                ClientCustomize cc = new ClientCustomize();
                string conStr = "";
                switch (Extension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, FilePath, isHDR);
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();

                //Insert into database CandidatesBulkImport table
                if (dt.Rows.Count > 0)
                {
                    //string lblMsg = clsCommanMethod.MsgBox("Total Candidates : " + dt.Rows.Count.ToString());
                    int countSuccess = 0;
                    int countDuplicate = 0;
                    string Email = string.Empty;
                    string MobileNo = string.Empty;
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        Email = Convert.ToString(dt.Rows[i]["STR_CANDIDATE_EMAIL"]);

                        model.EmailID = Email;
                        MobileNo = Convert.ToString(dt.Rows[i]["Contact Number"]);
                        if (MobileNo.Length > 10)
                        {
                            if (MobileNo.Length == 12)
                            {
                                model.MobileNo = MobileNo.Remove(0, 2);
                            }
                            else if (MobileNo.Length == 11)
                            {
                                model.MobileNo = MobileNo.Remove(0, 1);
                            }
                            else if (MobileNo.Length == 13)
                            {
                                model.MobileNo = MobileNo.Remove(0, 3);
                            }
                        }
                        model.MobileNo = MobileNo;
                        model.Name = dt.Rows[i]["EMPLOYEE_NAME"].ToString();
                        model.VoterIDCardNo = null;
                        string packageName = dt.Rows[i]["ACCOUNT_NAME"].ToString();
                        string PatternName = dt.Rows[i]["BGV_PATTERN_NAME"].ToString();
                        string countryName = dt.Rows[i]["COUNTRY"].ToString();
                        model.DrivingLicenseNo = null;
                        model.AadhaarCardNo = null;
                        model.PassportNo = null;
                        //========================================================
                        model.Education = dt.Rows[i]["Education"].ToString();
                        model.Employment = dt.Rows[i]["Employment"].ToString();
                        model.Address = dt.Rows[i]["Address"].ToString();
                        model.Criminal = dt.Rows[i]["Criminal"].ToString();
                        model.Identity = dt.Rows[i]["Identity"].ToString();
                        model.Database = dt.Rows[i]["Database"].ToString();
                        model.Additional_Professional_Certifications = dt.Rows[i]["Additional Professional Certifications"].ToString();
                        model.Drug_Test_Verification = dt.Rows[i]["Drug Test Verification"].ToString();
                        model.Credit_History_Verification = dt.Rows[i]["Credit History Verification"].ToString();
                        model.Family_Relationship = dt.Rows[i]["Family Relationship"].ToString();
                        model.External_Directorship = dt.Rows[i]["External Directorship"].ToString();
                        model.Self_Employment_Directorship = dt.Rows[i]["Self Employment/Directorship"].ToString();
                        model.Facis_III = dt.Rows[i]["Facis III"].ToString();
                        model.Entitlement_to_Work = dt.Rows[i]["Entitlement to Work"].ToString();
                        model.Professional_Reference_Verification = dt.Rows[i]["Professional Reference Verification"].ToString();
                        model.Professional_License_Check = dt.Rows[i]["Professional License Check"].ToString();
                        //========================================================
                        model.PanCardNo = null;
                        model.FatherName = null;
                        model.MiddleName = null;
                        model.ClientRefID = dt.Rows[i]["RESUME_NUMBER"].ToString();
                        model.LastName = null;
                        if (dt.Rows[i]["Date of Birth"].ToString() != "")
                            model.DOB = Convert.ToDateTime(dt.Rows[i]["Date of Birth"].ToString());
                        else
                            model.DOB = null;

                        if (!string.IsNullOrEmpty(model.Name))
                        {
                            //if(1==1)
                            //{ 
                            model.CreatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                            if (!repoPQPersonal.IsCandidateExistWiproBulk(model.ClientRowID, model.VoterIDCardNo, model.DrivingLicenseNo, model.AadhaarCardNo, model.PassportNo, model.PanCardNo, model.ClientRefID))
                            {
                                model.MiddleName = null;
                                model.LastName = null;
                                model.Gender = dt.Rows[i]["Gender"].ToString(); ;
                                if (model.Gender.ToLower() == "male")
                                {
                                    model.Gender = "Male";
                                    model.CandTitle = "Mr.";
                                }
                                else if (model.Gender.ToLower() == "female")
                                {
                                    model.CandTitle = "Mrs.";
                                }
                                else
                                {
                                    model.CandTitle = null;
                                }
                                model.EmployeeID = dt.Rows[i]["RESUME_NUMBER"].ToString();

                                model.CandidateCode = GenrateCandidateCode(model.ClientRowID);
                                model.CompanyRefNo = GetCompanyRefNo(model.ClientRowID);
                                model.CreatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                                model.CreatedDate = DateTime.Now;
                                model.FromType = "Company Cases";
                                model.DetailsEnteredBy = "Company";
                                model.CaseStatus = "Allocated";
                                model.Status = 1;
                                model.ClientUserName = null;
                                //if (dt.Rows[i]["DateofJoining"].ToString().Length > 4)
                                //{
                                model.DateofJoining = null;
                                //Convert.ToDateTime(dt.Rows[i]["DateofJoining"].ToString());
                                // }
                                model.PlaceOfJoining = null;
                                //dt.Rows[i]["PlaceOfJoining"].ToString();
                                model.AlternateNo = null;
                                model.ProcessName = null;
                                model.ProjectId = null;
                                model.ProjectName = null;


                                model.Grade = "";

                                model.UAN = dt.Rows[i]["UAN"].ToString();



                                model.PID = "";
                                model.SDO_Code = "";
                                model.COE_Code = "";
                                model.UID = "";
                                model.OHR_Taleo_ID = "";
                                model.Band = "";
                                model.Designation_Genpact = "";

                                model.AlternateEmailID = null;
                                model.Entity = dt.Rows[i]["Entity"].ToString();
                                model.AccountName = dt.Rows[i]["ACCOUNT_NAME"].ToString();
                                model.PatternName = dt.Rows[i]["BGV_PATTERN_NAME"].ToString();
                                model.CandidateType = null;


                                model.Location = "";



                                //if (Designation == "Team Leader-CS")
                                //{
                                model.CreatedBySource = "InternalBulkWiproSpoc";
                                //  }
                                PQClientCodeHolidaysViewModel client = repoPQClient.GetPQClientCodeHolidaysById(model.ClientRowID);
                                model.TAT = repoPQPersonal.GetClientTATByCandidateId(model.ClientRowID);
                                model.CaseType = "Normal";

                                // OrderDate And DeliveryDate
                                DateTime oDate = DateTime.Now;
                                model.OrderDate = oDate;
                                model.DeliveryDate = GetDeliveryDate(oDate, model.TAT, client);
                                DataTable dtuser = cc.getClientUserIdByName(model.ClientUserName, model.ClientRowID);
                                if (dtuser.Rows.Count > 0)
                                {
                                    model.ClientUserRowID = Convert.ToInt32(dtuser.Rows[0]["ClientUserRowID"]);
                                }
                                else
                                {
                                    model.ClientUserRowID = 0;
                                }
                                //// Check Duplicate Name
                                model.CandidateDuplicateList = repoPQPersonal.CheckCandidateduplicateNameFromDETL(model.ClientRowID, model.Name, model.MiddleName, model.LastName, "", model.MobileNo,model.EmployeeID);
                                if (model.CandidateDuplicateList.Count() > 0)
                                {
                                    cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, true, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);

                                }
                                else
                                {
                                    cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, false, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);
                                }
                                int Res = 0;

                                if (model.CandidateDuplicateList.Count() == 0)
                                {
                                    Res = repoPQPersonal.AddCandidateNew(model);
                                    model.PersonalRowID = Res;
                                }
                                else
                                {
                                    Res = -1;
                                }
                                if (Res == 0)
                                {
                                    ViewBag.ErrorMsg = ViewBag.ErrorMsg + " Mobile no and email id should not be duplicate";
                                }
                                else
                                {
                                    ViewBag.ErrorMsg = "Reference Generated Successfully";
                                }



                                if (Res > 0)
                                {
                                    //model.PersonalRowID = repoPQPersonal.GetPQPersonalByCandidateCode(model.CompanyRefNo).PersonalRowID;

                                    #region Save LogTransaction Details
                                    clsCommonMethods.AddPQLogTrasaction(model.PersonalRowID, "Add Candidate", "Candidate Reference Generated", "Input", "Insert");
                                    #endregion

                                    #region Case/Check Action History Save 
                                    clsCommonMethods.AddCaseActionHistory(model.PersonalRowID, "Allocated-TL", "Securitas Id Generated by Import: " + model.CompanyRefNo);
                                    #endregion

                                    SavePackageOrCheckWithCandidateAsBulkImportDOP(model, packageName, countryName, PatternName);
                                    cc.UpdateCaseStatus(model.PersonalRowID, 6, 0);
                                    countSuccess++;

                                }
                            }
                            else
                            {
                                cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, true, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);
                                countDuplicate++;
                            }

                        }

                    }




                    TempData["SuccessMsg"] = countSuccess.ToString() + " Candidate(s) added successfully!";
                    if (countDuplicate > 0)
                    {
                        TempData["ErrorMsg"] = countDuplicate.ToString() + " Candidate(s) already exist!";
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "No candidate found!";
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }

