                                        //file.SaveAs(filePath1);
                                    }
                                    System.IO.File.Delete(extractedFilePath);
                                }

                                if (Directory.Exists(pathtoget) && Directory.GetFiles(pathtoget).Length == 0)
                                {
                                    Directory.Delete(pathtoget);
                                }


                            }


                        }
                    }

                    ViewBag.Message = "Files uploaded successfully!";
                    return View();
                }

                ViewBag.Message = "No files selected.";
                return View();
            }
            catch (Exception ex)
            {

                string pathh = Server.MapPath(Path.Combine("~/Documents/Extracted/", ""));
                if (Directory.Exists(pathh))
                {
                    Directory.Delete(pathh, true);
                }
                throw;
            }
        }
