        {
            try
            {
                ClientCustomize cc = new ClientCustomize();
                DataTable dt = cc.GetWTSowData(packageName, PatternName);
                List<BulkCandidateImportWipro> SowModelWTList = new List<BulkCandidateImportWipro>();
                if (dt.Rows.Count > 0)
                {
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        BulkCandidateImportWipro SowModelWT = new BulkCandidateImportWipro();
                        SowModelWT.GCC_CODE = dt.Rows[i]["GCC_CODE"].ToString().Trim();
                        SowModelWT.ACCOUNT_NAME = dt.Rows[i]["ACCOUNT_NAME"].ToString().Trim();
                        SowModelWT.COUNTRY = dt.Rows[i]["COUNTRY"].ToString().Trim();
                        SowModelWT.PATTERNNAME = dt.Rows[i]["PATTERNNAME"].ToString().Trim();
