                        {

                            if (res.BGV_CHECK_SHORT == "Address Verification")
                            {
                                var ChekData = repoClientCheck.GetChecksByClientId(chekModel.ClientRowID).Where(p => p.SubCheckFamillyName == "Current " + res.BGV_CHECK_SHORT).FirstOrDefault();
                                if (ChekData != null)
                                {
                                    cc.WipROBulkCaseInitPQCandidateChecks(chekModel.ClientRowID, chekModel.PersonalRowID, "Current " + res.BGV_CHECK_SHORT, 0, ChekData.ClientCheckRowID);

