        private void ImportExcelAndSaveCandidateByBulkUpload(string FilePath, string Extension, string isHDR, AddPQPersonalBulkImportViewModel model, string TicketNo) //isHDR - means Include header Yes or No
        {
            try
            {
                string Designation = Session["Designation"].ToString();
                ClientCustomize cc = new ClientCustomize();
                string conStr = "";
                switch (Extension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, FilePath, isHDR);
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();

                //Insert into database CandidatesBulkImport table
                if (dt.Rows.Count > 0)
                {
                    //if (dt.Rows.Count < 20)
                    //{
                    //    throw new Exception("minimum allowed records in Excel are 20. Please Increase the number of cases.");
                    //}

                    //string lblMsg = clsCommanMethod.MsgBox("Total Candidates : " + dt.Rows.Count.ToString());
                    int countSuccess = 0;
                    int countDuplicate = 0;
                    string Email = string.Empty;
                    string MobileNo = string.Empty;
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        Email = Convert.ToString(dt.Rows[i]["Email"]);

                        model.EmailID = Email;
                        MobileNo = Convert.ToString(dt.Rows[i]["Mobile"]);
                        if (MobileNo.Length > 10)
                        {
                            if (MobileNo.Length == 12)
                            {
                                model.MobileNo = MobileNo.Remove(0, 2);
                            }
                            else if (MobileNo.Length == 11)
                            {
                                model.MobileNo = MobileNo.Remove(0, 1);
                            }
                        }
                        model.MobileNo = MobileNo;
                        model.Name = dt.Rows[i]["Name"].ToString();
                        model.VoterIDCardNo = dt.Rows[i]["VoterIDCardNo"].ToString();
                        model.DrivingLicenseNo = dt.Rows[i]["DrivingLicenseNo"].ToString();
                        model.AadhaarCardNo = dt.Rows[i]["AadhaarCardNo"].ToString();
                        model.PassportNo = dt.Rows[i]["PassportNo"].ToString();
                        model.PanCardNo = dt.Rows[i]["PanCardNo"].ToString();
                        model.FatherName = dt.Rows[i]["FatherName"].ToString();
                        model.MiddleName = dt.Rows[i]["MiddleName"].ToString();
                        model.LastName = dt.Rows[i]["LastName"].ToString();
                        if (dt.Rows[i]["DOB"].ToString() != "")
                            model.DOB = Convert.ToDateTime(dt.Rows[i]["DOB"].ToString());
                        else
                            model.DOB = null;

                        if (!string.IsNullOrEmpty(model.Name))
                        {
                            //if(1==1)
                            //{ 
                            model.CreatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                            if (!repoPQPersonal.IsCandidateExist(model.ClientRowID, model.VoterIDCardNo, model.DrivingLicenseNo, model.AadhaarCardNo, model.PassportNo, model.PanCardNo))
                            {
                                model.MiddleName = dt.Rows[i]["MiddleName"].ToString();
                                model.LastName = dt.Rows[i]["LastName"].ToString();
                                model.Gender = dt.Rows[i]["Gender"].ToString();
                                if (string.IsNullOrEmpty(model.Gender) || model.Gender.ToLower() == "male")
                                {
                                    model.Gender = "male";
                                    model.CandTitle = "Mr.";
                                }
                                else
                                {
                                    model.CandTitle = "Ms.";
                                }
                                model.EmployeeID = dt.Rows[i]["EmployeID"].ToString();
                                model.ClientRefID = dt.Rows[i]["ClientRefID"].ToString();
                                model.CandidateCode = GenrateCandidateCode(model.ClientRowID);
                                model.CompanyRefNo = GetCompanyRefNo(model.ClientRowID);
                                model.CreatedBy = Convert.ToInt16(Session["TeamMemberRowID"]);
                                model.CreatedDate = DateTime.Now;
                                model.FromType = "Company Cases";
                                model.DetailsEnteredBy = "Company";
                                model.CaseStatus = "Allocated";
                                model.Status = 1;
                                model.ClientUserName = dt.Rows[i]["ClientUserName"].ToString();
                                if (dt.Rows[i]["DateofJoining"].ToString().Length > 4)
                                {
                                    model.DateofJoining = Convert.ToDateTime(dt.Rows[i]["DateofJoining"].ToString());
                                }
                                model.PlaceOfJoining = dt.Rows[i]["PlaceOfJoining"].ToString();
                                model.AlternateNo = dt.Rows[i]["AlternateNo"].ToString();
                                model.ProcessName = dt.Rows[i]["ProcessName"].ToString();
                                model.ProjectId = dt.Rows[i]["ProjectId"].ToString();
                                model.ProjectName = dt.Rows[i]["ProjectName"].ToString();
                                if (model.ClientRowID == 1057)//CTSIPL
                                {

                                    model.Grade = dt.Rows[i]["Grade"].ToString();
                                }
                                else
                                {
                                    model.Grade = "";
                                }
                                model.UAN = dt.Rows[i]["UAN"].ToString();
                                if (model.ClientRowID == 722)//Genpact
                                {
                                    model.PID = dt.Rows[i]["PID Number"].ToString();
                                    model.SDO_Code = dt.Rows[i]["SDO Code"].ToString();
                                    model.COE_Code = dt.Rows[i]["COE Code"].ToString();
                                    model.UID = dt.Rows[i]["UID Number"].ToString();
                                    model.OHR_Taleo_ID = dt.Rows[i]["OHR/Taleo ID"].ToString();
                                    model.Band = dt.Rows[i]["Band"].ToString();
                                    model.Designation_Genpact = dt.Rows[i]["Designation"].ToString();
                                }

                                else
                                {

                                    model.PID = "";
                                    model.SDO_Code = "";
                                    model.COE_Code = "";
                                    model.UID = "";
                                    model.OHR_Taleo_ID = "";
                                    model.Band = "";
                                    model.Designation_Genpact = "";

                                }
                                model.AlternateEmailID = dt.Rows[i]["AlternateEmail"].ToString();
                                model.Entity = dt.Rows[i]["Entity"].ToString();
                                model.CandidateType = dt.Rows[i]["CandidateType"].ToString();
                                if (model.ClientRowID == 1193)//TCSION iDZ & LISP
                                {

                                    model.Location = dt.Rows[i]["Zone"].ToString();
                                }
                                else
                                {
                                    model.Location = "";

                                }
                                if (model.ClientRowID == 1266)//Innovsource Services Private Limited - TCSiON Project
                                {

                                    model.Roles = dt.Rows[i]["Roles"].ToString();
                                }
                                if (model.ClientRowID == 1266)//Innovsource Services Private Limited - TCSiON Project
                                {

                                    model.Roles = dt.Rows[i]["Roles"].ToString();
                                }
                                if (model.ClientRowID == 869)//IFFCO KISSAN
                                {

                                    model.Region = dt.Rows[i]["Region"].ToString();
                                }
                                if (model.ClientRowID == 272)//Walsons Services Private Limited (Security Services)
                                {
                                    model.HubLocation = dt.Rows[i]["Hub & Location"].ToString();
                                }
                                else
                                {
                                    model.HubLocation = "";
                                }

                                if (model.ClientRowID == 869)//IFFCO KISSAN
                                {

                                    model.State = dt.Rows[i]["State"].ToString();
                                }
                                if (Designation == "Team Leader-CS" || Designation == "Manager-CS" || Designation == "Team Member-CS")
                                {
                                    model.CreatedBySource = "InternalBulk-SPOC";
                                }
                                PQClientCodeHolidaysViewModel client = repoPQClient.GetPQClientCodeHolidaysById(model.ClientRowID);
                                model.TAT = repoPQPersonal.GetClientTATByCandidateId(model.ClientRowID);
                                model.CaseType = "Normal";

                                // OrderDate And DeliveryDate
                                DateTime oDate = DateTime.Now;
                                model.OrderDate = oDate;
                                model.DeliveryDate = GetDeliveryDate(oDate, model.TAT, client);
                                DataTable dtuser = cc.getClientUserIdByName(model.ClientUserName, model.ClientRowID);
                                if (dtuser.Rows.Count > 0)
                                {
                                    model.ClientUserRowID = Convert.ToInt32(dtuser.Rows[0]["ClientUserRowID"]);
                                }
                                else
                                {
                                    model.ClientUserRowID = 0;
                                }
                                //// Check Duplicate Name
                                model.CandidateDuplicateList = repoPQPersonal.CheckCandidateduplicateNameFromDETL(model.ClientRowID, model.Name, model.MiddleName, model.LastName, "", model.MobileNo, model.EmployeeID);
                                if (model.CandidateDuplicateList.Count() > 0)
                                {
                                    cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, true, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);

                                }
                                else
                                {
                                    cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, false, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);
                                }
                                int Res = 0;

                                if (model.CandidateDuplicateList.Count() == 0)
                                {
                                    Res = repoPQPersonal.AddCandidate(model);
                                    model.PersonalRowID = Res;
                                }
                                else
                                {
                                    Res = -1;
                                }
                                if (Res == 0)
                                {
                                    ViewBag.ErrorMsg = ViewBag.ErrorMsg + " Mobile no and email id should not be duplicate";
                                }
                                else
                                {
                                    ViewBag.ErrorMsg = "Reference Generated Successfully";
                                }



                                if (Res > 0)
                                {
                                    //model.PersonalRowID = repoPQPersonal.GetPQPersonalByCandidateCode(model.CompanyRefNo).PersonalRowID;

                                    #region Save LogTransaction Details
                                    clsCommonMethods.AddPQLogTrasaction(model.PersonalRowID, "Add Candidate", "Candidate Reference Generated", "Input", "Insert");
                                    #endregion

                                    #region Case/Check Action History Save 
                                    clsCommonMethods.AddCaseActionHistory(model.PersonalRowID, "Allocated-TL", "Securitas Id Generated by Import(SPOC): " + model.CompanyRefNo);
                                    #endregion

                                    SavePackageOrCheckWithCandidateAsBulkImport(model);
                                    cc.UpdateCaseStatus(model.PersonalRowID, 6, 0);
                                    countSuccess++;
                                }
                            }
                            else
                            {
                                cc.Insert_DuplicateReferenceDetail(TicketNo, model.Name, model.MiddleName, model.LastName, model.MobileNo, model.CreatedBy.ToString(), model.EmailID, true, model.ClientRowID.ToString(), model.FatherName, "Internal", model.DOB);
                                countDuplicate++;
                            }
                        }
                    }

                    TempData["SuccessMsg"] = countSuccess.ToString() + " Candidate(s) added successfully!";
                    if (countDuplicate > 0)
                    {
                        TempData["ErrorMsg"] = countDuplicate.ToString() + " Candidate(s) already exist!";
                    }
                }
                else
                {
                    ViewBag.ErrorMsg = "No candidate found!";
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }

