                            return RedirectToAction("DeleteCase", "ClientServicing", new { Search = Search });
                        }
                        else
                        {
                            TempData["SuccessMsg"] = "Please fill all Details and move check!";

                        }

                    }




                }

                return View(model);



            }
            catch (Exception ex)
            {
                TempData["SuccessMsg"] = ex.Message;
                throw;
            }
        }

