                        var ws = wb.Worksheets.Add(dt);
                        ws.Tables.FirstOrDefault().ShowAutoFilter = false;
                        //wb.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                        wb.Style.Font.Bold = true;
                        Response.Clear();
                        Response.Buffer = true;
                        Response.Charset = "";
                        Response.ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                        Response.AddHeader("content-disposition", "attachment;filename=consolidated MIS auto Interim Gallagher.xlsx");

                        using (MemoryStream MyMemoryStream = new MemoryStream())
                        {
                            wb.SaveAs(MyMemoryStream);
                            MyMemoryStream.WriteTo(Response.OutputStream);
                            Response.Flush();
                            Response.End();
                        }
                    }
                }



            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
        }



        [HttpGet]
        public async Task<ActionResult> PurgeProcess()
        {
            //TempData["SuccessMessage"] = "";
            ClientCustomize cm = new ClientCustomize();
            var clientList = repoDDL.GetActiveClientList();
            DataTable dt = cm.GetPurgeRecords(0);
            ViewBag.PurgeRecords = dt;

           
            ViewBag.TotalRecords = dt != null ? dt.Rows.Count : 0;
            ViewBag.ClientList = new SelectList(clientList, "ClientRowID", "ClientName");
            return View(/*new PurgeFormSubmitModel()*/);
        }

        [HttpGet]
