            try
            {
                ClientCustomize cc = new ClientCustomize();
                DataTable dt = cc.GetPurgeRecords(Convert.ToInt32(id));

                if (dt != null && dt.Rows.Count > 0)
                {
                    string CertificateReferenceNo = dt.Rows[0]["Reference Number"].ToString();
                    string ClientName = dt.Rows[0]["ClientName"].ToString();
                    string ClientAddress = dt.Rows[0]["Customer Add."].ToString();
                    string Size = dt.Rows[0]["Size"].ToString();
                    string DateRange = dt.Rows[0]["Date range"].ToString();
                    string RequestedNo = dt.Rows[0]["RequestedNo"].ToString();

                    DateTime parsedDate = Convert.ToDateTime(dt.Rows[0]["FormattedCreatedOn"]);
                    int day = parsedDate.Day;
                    string suffix = "th";

                    if (day < 11 || day > 13)
                    {
                        switch (day % 10)
                        {
                            case 1: suffix = "st"; break;
                            case 2: suffix = "nd"; break;
                            case 3: suffix = "rd"; break;
                        }
                    }
                    string PurgedDate = $"{day}{suffix} {parsedDate:MMMM yyyy}";

                    // 3. Server par existing PDF template verify karna
                    string templatePath = Server.MapPath("~/Uploads/PurgingExcelFilesDetails/Templates/CertificateTemplate.pdf");

