                *This is an automated report hence no signature is required
            </div>

        </div>

    </div>");
                    }


                    if (string.IsNullOrEmpty(originalPdfHtml))
                    {
                        return HttpNotFound("Failed to extract HTML structure from the provided PDF template.");
                    }

                    // 5. Aapki original PDF se nikle HTML block ke andar values replace karna
                    originalPdfHtml = originalPdfHtml.Replace("{CertificateReferenceNo}", CertificateReferenceNo);
                    originalPdfHtml = originalPdfHtml.Replace("{ClientName}", ClientName);
                    originalPdfHtml = originalPdfHtml.Replace("{ClientAddress}", ClientAddress);
                    originalPdfHtml = originalPdfHtml.Replace("{Size}", Size);
                    originalPdfHtml = originalPdfHtml.Replace("{ReqNo}", RequestedNo);
                    originalPdfHtml = originalPdfHtml.Replace("{PurgedDate}", PurgedDate);

                    // originalPdfHtml = originalPdfHtml.Replace("{TableRows}", rowsHtml.ToString());
                    originalPdfHtml = originalPdfHtml.Replace("{AnnexurePages}", annexurePages.ToString());
                    // 6. IronPDF Chrome Renderer se is customized HTML ko final clean PDF banana
                    var renderer = new ChromePdfRenderer();
                    renderer.RenderingOptions.MarginTop = 0;
                    renderer.RenderingOptions.MarginBottom = 0;
                    renderer.RenderingOptions.MarginLeft = 10;
                    renderer.RenderingOptions.MarginRight = 10;
                    using (IronPdf.PdfDocument pdf = renderer.RenderHtmlAsPdf(originalPdfHtml))
                    {
                        byte[] finalPdfBytes = pdf.BinaryData;

                        string downloadFileName = $"Client_Documents_{ClientName.Replace(" ", "_")}_{DateTime.Now:yyyyMMdd_HHmmss}.pdf";

                        // Chrome is binary clean stream ko safely load karega bina kisi template error ke
                        return File(finalPdfBytes, "application/pdf", downloadFileName);
                    }
                }
                else
                {
                    return HttpNotFound("No records found for the given ID.");
                }
            }
            catch (Exception ex)
            {
                TempData["ErrorMessage"] = "Error during PDF to HTML conversion workflow: " + ex.Message;
                return RedirectToAction("PurgeProcess");
            }
        }

        [HttpGet]
        public async Task<ActionResult> PurgeProcessN(string purgeid ,string PurgeRecordid)
        {
            //TempData["SuccessMessage"] = "";
            ClientCustomize cm = new ClientCustomize();
            var clientList = repoDDL.GetActiveClientList();
            DataTable dt = cm.GetPurgeRecords(Convert.ToInt32(PurgeRecordid));

            ViewBag.PurgeRecords = dt;

            ViewBag.purgeid = purgeid;
            ViewBag.TotalRecords = dt != null ? dt.Rows.Count : 0;
            ViewBag.ClientList = new SelectList(clientList, "ClientRowID", "ClientName");
            return View(/*new PurgeFormSubmitModel()*/);
        }

        public string AutoGenerateAndEmailCertificate(string id, string Emailid)
        {
            try
