                TempData["SuccessMessage"] = "Select Valid client Name.";
                return View();
            }

            if (string.IsNullOrEmpty(fileNameReq))
            {
                ModelState.AddModelError("", "Select File Name is mandatory Field.");
                TempData["SuccessMessage"] = "Select File Name is mandatory Field.";
                return View();
            }
            if (string.IsNullOrEmpty(PurgDateFrom))
            {
                ModelState.AddModelError("", "Select Purge Date From is mandatory Field.");
                TempData["SuccessMessage"] = "Select Purge Date From is mandatory Field.";
                return View();
            }
            if (string.IsNullOrEmpty(PurgDateTo))
            {
                ModelState.AddModelError("", "Select Purge Date To is mandatory Field.");
                TempData["SuccessMessage"] = "Select Purge Date To is mandatory Field.";
                return View();
            }

            if (ExcelFile == null || ExcelFile.ContentLength == 0)
            {
                ModelState.AddModelError("", "Select Upload Excel File is mandatory Field.");
                TempData["SuccessMessage"] = "Select Upload Excel File is mandatory Field.";
                return View();
            }
            else
            {
                string extension = Path.GetExtension(ExcelFile.FileName).ToLowerInvariant();
                if (extension != ".xlsx")
                {
                    ModelState.AddModelError("", "Only .xlsx files are allowed.");
                    TempData["SuccessMessage"] = "Only .xlsx files are allowed.";
                    return View();
                }
            }

            if (!ModelState.IsValid)
            {
                TempData["SuccessMessage"] = "Form validation failed. Please provide valid details and try again.";
                return View();
            }

            try
            {

                System.Web.Hosting.HostingEnvironment.QueueBackgroundWorkItem(async cancellationToken =>
                {
                    await PurgeProcessing(ClientRowID, PurgDateFrom,PurgDateTo, fileNameReq, IsDocumentRequired, ExcelFile);
                });
                //var mes = await PurgeProcessing(ClientRowID, DateRange, IsDocumentRequired, ExcelFile);

                var mes = "The purging process has started successfully in the background. You can safely close this page or monitor the records grid.";

                TempData["SuccessMessage"] = mes;
                return View();
            }
            catch (Exception ex)
            {
                TempData["SuccessMessage"] = "Error : " + ex.Message;
                return View();
            }
        }

