        public async Task<byte[]> DownloadNewAndZipReportsAsync(DataTable dt)
        {
            using (var memoryStream = new MemoryStream())
            {
                using (var archive = new ZipArchive(memoryStream, ZipArchiveMode.Create, true))
                {
                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        string fileName = dt.Rows[i]["CompanyRefNo"].ToString();
                        DocumentResponse document = null;

                        document = await TryGetDocumentAsync("46", fileName, "D:/path_for_46/");

                        if (document == null)
                        {
                            document = await TryGetDocumentAsync("76", fileName, "D:/path_for_76/");
                        }

                        if (document == null)
                        {
                            document = await TryGetDocumentAsync("55", fileName, "D:/path_for_55/");
                        }

                        if (document != null && !string.IsNullOrEmpty(document.DocumentValue))
                        {
                            byte[] fileBytes = Convert.FromBase64String(document.DocumentValue);
                            string finalFileName = !string.IsNullOrEmpty(document.DocumentName) ? document.DocumentName : fileName;

                            var zipEntry = archive.CreateEntry($"reports/{finalFileName}");

                            using (var entryStream = zipEntry.Open())
                            {
                                await entryStream.WriteAsync(fileBytes, 0, fileBytes.Length);
                            }
                        }
                    }
                }
                return memoryStream.ToArray();
            }
        }
