        private async Task<DocumentResponse> TryGetDocumentAsync(string clientType, string fileName, string path)
        {
            try
            {
                DocumentService documentService = new DocumentService();
                HttpResponseMessage getResponse = null;

             
                switch (clientType)
                {
                    case "46": getResponse = await documentService.GetDocumentAsync46(fileName, path); break;
                    case "76": getResponse = await documentService.GetDocumentAsync76(fileName, path); break;
                    case "55": getResponse = await documentService.GetDocumentAsync55(fileName, path); break;
                    default: return null;
                }

             
                if (getResponse == null || !getResponse.IsSuccessStatusCode)
                {
                    return null;
                }

              
                var jsonString = await getResponse.Content.ReadAsStringAsync();
                var documentResult = JsonConvert.DeserializeObject<DocumentResponse>(jsonString);

              
                getResponse.Dispose();

            
                try
                {
                    HttpResponseMessage deleteResponse = null;
                    switch (clientType)
                    {
                        case "46": deleteResponse = await documentService.DeleteDocumentAsync46(fileName, path); break;
                        case "76": deleteResponse = await documentService.DeleteDocumentAsync76(fileName, path); break;
                        case "55": deleteResponse = await documentService.DeleteDocumentAsync55(fileName, path); break;
                    }

                 
                    deleteResponse?.Dispose();
                }
                catch (Exception deleteEx)
                {
                   
                }

            
                return documentResult;
            }
            catch (Exception ex)
            {
                 
                return null;
            }
        }

