        [NonAction]
        int BindCheckList(string RefNo = "")
        {
            int clientRowId = 0;
            try
            {
                var list = repoDDL.BindChecksDetails(RefNo);
                if (list.Count() >= 1)
                {
                    ViewBag.CheckList = list;
                    var a = list.ToList();
                    clientRowId = a[0].ClientRowID;
                }

            }
            catch (Exception)
            {

                throw;
            }
            return clientRowId;
        }





