            {
                if (cid > 0 && scid > 0 && pe > 0)
                {
                    DataTable dtcurrent = cc.GetCandidateCheckId(pe, Convert.ToInt32(scid));
                    if (dtcurrent.Rows.Count > 0)
                    {

                        CandCheckRowid = Convert.ToInt32(dtcurrent.Rows[0]["CandCheckRowID"].ToString());
                    }
                    model.CheckRowID = CandCheckRowid;
                    model.ClientRowID = cid;
                    model.SubCheckRowID = scid;
                    model.PersonalRowID = pe;
                    model.checkStatusid = checkStatusid;
                    model.Insufftype = InsuffType;

                    int checkfamilyrowid = 0;
                    DataTable dtcheck1 = cc.GetSubCheckFamilyForUpdateById(Convert.ToInt16(model.SubCheckRowID));
                    if (dtcheck1.Rows.Count > 0)
                    {
                        checkfamilyrowid = Convert.ToInt32(dtcheck1.Rows[0]["CheckFamilyRowID"].ToString());
                    }

                    Session["Mode"] = 0;
                    Session["checkfamilyrowids"] = checkfamilyrowid;
                    Session["CheckFamilRowId"] = checkfamilyrowid;
                    Session["InsuffType"] = InsuffType;
                }
                else
                {
                    TempData["ErrorMsg"] = "invlid id!";
                }
            }
            catch (Exception Ex)
            {
                ViewBag.ErrorMsg = Ex.Message;
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }
            return View(model);
        }

