        [HttpGet]
        [SessionExpireFilterAttribute]
        public JsonResult GetTCSMailData(string fromDate = "", string toDate = "")
        {
            List<object> list = new List<object>();
            try
            {
                ClientCustomize objCC = new ClientCustomize();
                DataTable dt;


                dt = objCC.GetTCSMailData();


                if (!string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(toDate))
                {
                    DateTime dtFrom, dtTo;
                    if (DateTime.TryParse(fromDate, out dtFrom) && DateTime.TryParse(toDate, out dtTo))
                    {
                        DataTable filteredTable = dt.Clone();
                        foreach (DataRow row in dt.Rows)
                        {
                            if (dt.Columns.Contains("MailDateTime") && row["MailDateTime"] != DBNull.Value)
                            {
                                DateTime mailDate;
                                if (DateTime.TryParse(row["MailDateTime"].ToString(), out mailDate))
                                {
                                    if (mailDate.Date >= dtFrom.Date && mailDate.Date <= dtTo.Date)
                                    {
                                        filteredTable.ImportRow(row);
                                    }
                                }
                            }
                        }
                        dt = filteredTable;
                    }
                }

                if (dt != null && dt.Rows.Count > 0)
                {
                    int srNo = 1;
                    bool hasCoordinatorName = dt.Columns.Contains("CoordinatorName");
                    bool hasMailDateTime = dt.Columns.Contains("MailDateTime");
                    foreach (DataRow dr in dt.Rows)
                    {
                        string mailDateTimeValue = "";
                        if (hasMailDateTime && dr["MailDateTime"] != DBNull.Value && !string.IsNullOrWhiteSpace(dr["MailDateTime"].ToString()))
                        {
                            DateTime dtMail;
                            if (DateTime.TryParse(dr["MailDateTime"].ToString(), out dtMail))
                            {
                                mailDateTimeValue = dtMail.ToString("dd-MM-yyyy HH:mm:ss");
                            }
                            else
                            {
                                mailDateTimeValue = dr["MailDateTime"].ToString();
                            }
                        }

                        list.Add(new
                        {
                            SrNo = srNo++,
                            ApplicantName = dr.Table.Columns.Contains("ApplicantName") && dr["ApplicantName"] != DBNull.Value ? dr["ApplicantName"].ToString() : "",
                            ApplicantID = dr.Table.Columns.Contains("ApplicantID") && dr["ApplicantID"] != DBNull.Value ? dr["ApplicantID"].ToString() : "",
                            CoordinatorName = hasCoordinatorName && dr["CoordinatorName"] != DBNull.Value ? dr["CoordinatorName"].ToString() : "",
                            MailDateTime = mailDateTimeValue
                        });
                    }
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            return Json(list, JsonRequestBehavior.AllowGet);
        }



        [SessionExpireFilterAttribute]
        public ActionResult ExportTCSMailData()
        {
            try
            {
                ClientCustomize objCC = new ClientCustomize();
                DataTable dt = objCC.GetTCSMailData();
                if (dt != null && dt.Rows.Count > 0)
                {
                    ExportToExcel(dt, "TCSMailData");
                }
            }
            catch (Exception Ex)
            {
                clsCommonMethods.ErrorLog(Server.MapPath("~\\ErrorLogs\\Logfiles"), Ex.Message, Ex.StackTrace);
            }

            return RedirectToAction("TCSmaildata");
        }

