        {
            Candidate_InformationViewModel model = new Candidate_InformationViewModel();
            PersonalRowID = clsCommonMethods.PDecrypt(PersonalRowID);
            ClientCustomize cc = new ClientCustomize();
            DataTable dt3 = new DataTable();
