        [HttpPost]
        [SessionExpireFilterAttribute]
        public ActionResult TCSIonCriminalAddCheck(HttpPostedFileBase fileUpload)
        {
            if (fileUpload != null && fileUpload.ContentLength > 0)
            {
                var fileName = Path.GetFileName(fileUpload.FileName);

                var fileExtension = Path.GetExtension(fileName).ToLower();
                if (fileExtension != ".xls" && fileExtension != ".xlsx")
                {
                    ViewBag.Message = "Invalid file type. Please upload an Excel file.";
                    return View();
                }
       
                if (fileExtension == ".xls")
                {
                    ViewBag.Message = $"Please Upload .xlsx file only.";

                    return View();
                }
                var fileNameOnly = Path.GetFileNameWithoutExtension(fileUpload.FileName);
                var uniqueFileName = $"{fileNameOnly}_{Guid.NewGuid()}{fileExtension}";
                var filePath = Path.Combine(Server.MapPath("~/Uploads/BulkClosureUploads/"), uniqueFileName);

                var directoryPath = Path.GetDirectoryName(filePath);
                if (!Directory.Exists(directoryPath))
                {
                    Directory.CreateDirectory(directoryPath);
                }

                fileUpload.SaveAs(filePath);

                //==============================================
                string conStr = "";
                switch (fileExtension)
                {
                    case ".xls": //Excel 97-03
                        conStr = ConfigurationManager.ConnectionStrings["Excel03ConString"].ConnectionString;
                        break;
                    case ".xlsx": //Excel 07
                        conStr = ConfigurationManager.ConnectionStrings["Excel07ConString"].ConnectionString;
                        break;
                }
                conStr = String.Format(conStr, filePath, "Yes");
                OleDbConnection connExcel = new OleDbConnection(conStr);
                OleDbCommand cmdExcel = new OleDbCommand();
                OleDbDataAdapter oda = new OleDbDataAdapter();
                DataTable dt = new DataTable();

          
                cmdExcel.Connection = connExcel;

                //Get the name of First Sheet
                connExcel.Open();
                DataTable dtExcelSchema;
                dtExcelSchema = connExcel.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, null);
                string SheetName = dtExcelSchema.Rows[0]["TABLE_NAME"].ToString();
                connExcel.Close();

                //Read Data from First Sheet
                connExcel.Open();
                cmdExcel.CommandText = "SELECT * From [" + SheetName + "]";
                oda.SelectCommand = cmdExcel;
                oda.Fill(dt);
                connExcel.Close();
                if (dt.Rows.Count > 0)
                {
                    if(dt.Rows.Count > 500)
                    {
                        ViewBag.Message = $"Only 500 Data should be uploaded at a time.";
                        return View();
                    }
                    foreach (DataRow row in dt.Rows)
                    {
                        foreach (DataColumn col in dt.Columns)
                        {
                          
                            if (row[col].GetType() != typeof(string) && row[col] != DBNull.Value)
                            {
                                ViewBag.Message = $"Error: Column '{col.ColumnName}' is not is Text format. Please Ensure all Data in Excel Should be in Text format.";
                                return View();
                            }
                        }
                    }

                    var uniqueRows = dt.AsEnumerable()
       .Where(row => !row.IsNull("Reference ID") && !string.IsNullOrWhiteSpace(row["Reference ID"].ToString()))
       .GroupBy(row => row.Field<string>("Reference ID"))
       .Select(g => g.First())
       .CopyToDataTable();

                    ClientCustomize cm = new ClientCustomize();
                    DataTable dto =  cm.CheckTCSiONExistInDb(uniqueRows);
                   // dto.Columns.Add("DateFormatted", typeof(string));

                   // // 2. Date ko format karke naye column mein dalein
                   // foreach (DataRow row in dto.Rows)
                   // {
                   //     if (row["Date_Of_Birth"] != DBNull.Value)
                   //     {
                   //         DateTime dtc = Convert.ToDateTime(row["Date_Of_Birth"]);
                   //         row["DateFormatted"] = dtc.ToString("dd-MM-yyyy"); // Exact format 25-09-2003
                   //     }
                   // }

                   // //3.Purane column ko delete karein aur naye ka naam change karein

                   //dto.Columns.Remove("Date_Of_Birth");
                   // dto.Columns["DateFormatted"].ColumnName = "Date_Of_Birth";
                  cm.CheckTCSiONExistInDb(1127, dto);


                }
                //==============================================


                ViewBag.Message = "File uploaded successfully!";
            }
            else
            {
                ViewBag.Message = "No file selected!";
            }


            return View();
        }

