        [HttpGet]
        [SessionExpireFilterAttribute]
        [ValidateInput(false)]
        public ActionResult QCRejectionsClient()
        {
            ClientCustomize cc = new ClientCustomize();
            List<QCRejectionClient> QCReject = new List<QCRejectionClient>();
            DataTable dt = new DataTable();
            dt = cc.GetQCRejectionclientCases();
            if (dt.Rows.Count>0)
            {
                foreach(DataRow row in dt.Rows)
                {
                    QCRejectionClient model = new QCRejectionClient();
                    model.Personalrowid = Convert.ToInt32(row["PersonalRowID"]);
                    model.ResumeID = Convert.ToString(row["ClientRefID"]);
                    model.SecuritasID = Convert.ToString(row["CompanyRefNo"]);
                    model.CandidateName = Convert.ToString(row["CandidateFullName"]);
                    model.QCRejectionDate = Convert.ToString(row["QCRejectionDate"]);
                    model.CheckDetails = "";
                    model.QCRejectionRemarks = Convert.ToString(row["QCRejectionRemarks"]);
                    model.Documents = Convert.ToString(row["Documents"]);
                    QCReject.Add(model);

                }

                ViewBag.Data = QCReject;
            }

            return View();
        }

    }
